 [UnityTest]public IEnumerator R18HeroIntegration(){Directory.CreateDirectory(Evidence);var file=Path.Combine(Evidence,"models-integration.json");Assert.That(File.Exists(file),Is.False);var r=new R18ModelsReport();Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(r,true));yield return NewRetrySubject(false,true,true,true,true,true,true);var panels=ObjectPanelsR18();Assert.That(panels.Count,Is.EqualTo(3));r.objectBefore=ObjectContractR18(panels);foreach(var p in panels)StaticCall(RuntimeType("MallModelPackR18"),"Restore",Field(p,"city2"));yield return null;UnityEngine.Physics.SyncTransforms();string restored=ObjectContractR18(panels);foreach(var p in panels)StaticCall(RuntimeType("MallModelPackR18"),"Apply",Field(p,"city2"));UnityEngine.Physics.SyncTransforms();r.objectAfter=ObjectContractR18(panels);r.objectContractEqual=r.objectBefore==restored&&restored==r.objectAfter;r.noNewObjectPhysics=true;foreach(var p in panels){var v=(Component)Field(p,"city2");var marker=v.GetComponent(RuntimeType("MallObjectBindingR18"));if(marker){r.objectBindings++;foreach(GameObject go in (IEnumerable)Field(marker,"generated"))r.noNewObjectPhysics&=go.GetComponentsInChildren<Collider>(true).Length==0&&go.GetComponentsInChildren<Rigidbody>(true).Length==0;}}r.bayCount=current.transform.Cast<Transform>().Count(t=>t.name=="R18 representative boutique bay");Assert.That(r.objectContractEqual&&r.noNewObjectPhysics&&r.objectBindings==3&&r.bayCount==1,Is.True);save();
