 r.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents")){var row=new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")};r.naturalBreaks.Add(row);if(r18Ids.Contains(row.id))r.naturalTargetBreaks.Add(row.id);}Assert.That(captured,Is.True);CaptureRoute("combined-result","same");Call(current,"RetryLaunch","");yield return null;r.retry=HeroSnapshotR18();Assert.That(r.retry.heroLayers==1&&r.retry.visibleMeshes==35,Is.True);Assert.That(current.transform.Cast<Transform>().Count(t=>t.name=="R18 representative boutique bay"),Is.EqualTo(1));
