 [UnityTest]public IEnumerator R18FadeGlassOnly(){Directory.CreateDirectory(Evidence);string output=Path.Combine(Evidence,"glass-ray.json");Assert.That(File.Exists(output),Is.False);yield return NewRetrySubject(false,true,true,true,true,true,true);Call(current,"ReviewReplayAccepted",File.ReadAllText(Environment.GetEnvironmentVariable("CRAB_R18_SAVED_LAUNCH")));var sim=WorldR18();string target="street3-+1-11-market_crate";Call(sim,"ReviewRouteSegmentR11",target);bool broke=false;for(int i=0;i<180&&!broke;i++){Call(current,"Tick",1f/60);foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))if((string)Field(e,"id")==target)broke=true;}for(int i=0;i<8;i++)Call(current,"Tick",1f/60);Call(current,"ReviewRefreshFragmentVisibility",true);int slots=0,tests=0;bool preserved=true,excluded=true,found=false;foreach(DictionaryEntry pair in (IDictionary)Field(sim,"visibilityRecords")){var item=pair.Value;var renderer=(Renderer)Field(item,"renderer");excluded&=renderer.enabled;var original=(Material[])Field(item,"original");var faded=(Material[])Field(item,"faded");var mesh=(Mesh)Field(item,"mesh");for(int sub=0;sub<Mathf.Min(mesh.subMeshCount,original.Length);sub++){var mat=original[sub];if(!mat||!(mat.renderQueue>=3000||mat.GetTag("RenderType",false)=="Transparent"))continue;slots++;preserved&=mat==faded[sub];if(found)continue;var vs=mesh.vertices;var tri=mesh.GetTriangles(sub);for(int k=0;k+2<tri.Length&&k<96;k+=3){var a=renderer.transform.TransformPoint(vs[tri[k]]);var b=renderer.transform.TransformPoint(vs[tri[k+1]]);var c=renderer.transform.TransformPoint(vs[tri[k+2]]);var norm=Vector3.Cross(b-a,c-a).normalized;if(norm.sqrMagnitude<.5f)continue;var ray=new Ray((a+b+c)/3+norm*.005f,-norm);var localOrigin=renderer.transform.InverseTransformPoint(ray.origin);var localDir=renderer.transform.InverseTransformVector(ray.direction);bool oldHit=Convert.ToBoolean(sim.GetType().GetMethod("ReviewRayTriangle").Invoke(null,new object[]{localOrigin,localDir,vs[tri[k]],vs[tri[k+1]],vs[tri[k+2]],.01f}));bool newHit=Convert.ToBoolean(Call(sim,"MeshBlocks",item,ray,.06f));tests++;if(oldHit&&!newHit){found=true;break;}}}}File.WriteAllText(output,JsonUtility.ToJson(new R18GlassProbe{actualTargetBroken=broke,transparentSlots=slots,transparentMaterialPreserved=preserved,disabledDonorsExcluded=excluded,glassOnlyLegacyHitFilteredOut=found,actualGlassTriangleRayTests=tests,final=JsonUtility.ToJson(State(current))},true));Assert.That(broke&&slots>0&&preserved&&excluded&&found,Is.True,"actual metal/glass fragment visibility path");Call(current,"Prepare","");yield return null;Call(current,"ReviewReplayAccepted",File.ReadAllText(Environment.GetEnvironmentVariable("CRAB_R18_SAVED_LAUNCH")));sim=WorldR18();Call(sim,"ReviewDropPose",Quaternion.Euler(180,90,0),new Vector3(0,-4,0),Vector3.zero);bool shellHit=false;for(int i=0;i<240&&!shellHit;i++){Call(current,"Tick",1f/60);shellHit=Convert.ToInt32(Field(sim,"LastKind"))==1&&new[]{"sand","float"}.Contains((string)Field(sim,"LastSurface"));}var shell=new R18ShellProbe{fixture="explicit shell-down vertical drop from8m using existing ReviewDropPose, not natural gameplay reach",shellContact=shellHit,final=JsonUtility.ToJson(State(current))};if(shellHit){DetachHeroR18();yield return null;shell.before=HeroSnapshotR18();CaptureRoute("shell-r17","same");AttachHeroR18();shell.after=HeroSnapshotR18();CaptureRoute("shell-r2","same");shell.physicsEqual=HeroSameR18(shell.before,shell.after);Assert.That(shell.physicsEqual,Is.True);}File.WriteAllText(Path.Combine(Evidence,"shell-contact.json"),JsonUtility.ToJson(shell,true));Call(current,"ShutdownReviewPhysics");current=null;yield return null;}
 [UnityTest]public IEnumerator R18ShellContactOnly(){Directory.CreateDirectory(Evidence);yield return NewRetrySubject(false,true,true,true,true,true,true);Call(current,"ReviewReplayAccepted",File.ReadAllText(Environment.GetEnvironmentVariable("CRAB_R18_SAVED_LAUNCH")));var sim=WorldR18();Call(sim,"ReviewDropPose",Quaternion.Euler(180,90,0),new Vector3(0,-4,0),Vector3.zero);bool hit=false;for(int i=0;i<240&&!hit;i++){Call(current,"Tick",1f/60);hit=Convert.ToInt32(Field(sim,"LastKind"))==1&&(string)Field(sim,"LastPart")=="shell";}var report=new R18ShellProbe{fixture="same shell-down8m fixture, accepts actual observed tank shell contact; not natural gameplay or floor-contact evidence",shellContact=hit,final=JsonUtility.ToJson(State(current))};if(hit){DetachHeroR18();yield return null;report.before=HeroSnapshotR18();CaptureRoute("shell-r17","same");AttachHeroR18();report.after=HeroSnapshotR18();CaptureRoute("shell-r2","same");report.physicsEqual=HeroSameR18(report.before,report.after);Assert.That(report.physicsEqual,Is.True);}File.WriteAllText(Path.Combine(Evidence,"shell-contact.json"),JsonUtility.ToJson(report,true));Assert.That(hit,Is.True);Call(current,"ShutdownReviewPhysics");current=null;yield return null;}
